using System.Collections.Generic;
using DG.Tweening;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "ChooseDiceStateJoystickAction", menuName = "Data/Battle/Actions/ChooseDiceStateJoystickAction")]
public class ChooseDiceStateJoystickAction : Action
{
	private enum ChooseDiceStateEnum
	{
		AllDice,
		OnlyEnemyDice,
		PlayerHandDice
	}

	[Header("Choose Dice State Enum")]
	[SerializeField]
	private ChooseDiceStateEnum chooseDiceStateEnum;

	[Header("Reference")]
	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	[SerializeField]
	private DiceTargetCastSpaceInstancesReference diceTargetCastSpaceInstancesReference;

	[Header("Event")]
	[SerializeField]
	private VoidEvent OnCancelActionButtonPressedJoystick;

	[SerializeField]
	private VoidEvent OnCastActionButtonPressedJoystick;

	[SerializeField]
	private VoidEvent OnShowChooseDiceSlotCanvas;

	[SerializeField]
	private VoidEvent OnMovedToDiceInstanceChooseDiceState;

	private List<ZoomableInstance> enemiesAndCompanionOriginalHorizontalZoomableList = new List<ZoomableInstance>();

	private List<ZoomableInstance> playerOriginalHorizontalZoomableList = new List<ZoomableInstance>();

	private bool freezeInput;

	private List<DiceTargetCastSpaceInstance> diceTargetCastSpaceInstances => diceTargetCastSpaceInstancesReference.diceTargetCastSpaceInstances;

	public override void OnStartState()
	{
		OnShowChooseDiceSlotCanvas.Raise();
		base.OnStartState();
		if (chooseDiceStateEnum == ChooseDiceStateEnum.AllDice)
		{
			base.inputManager.SetVerticalIndex(1);
			int index = 0;
			int index2 = 0;
			int count = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices.Count;
			List<DiceInstance> handDices = ReferenceSingleton<PlayerDiceHandHolder>.Instance.handDices;
			bool hasDiceOnHand = false;
			if (count == 1)
			{
				if (handDices.First() != actionInstanceReference.Value)
				{
					hasDiceOnHand = true;
					index = 1;
					index2 = 1;
					AddDiceOnHandToVerticalList();
				}
				else
				{
					hasDiceOnHand = false;
				}
			}
			else if (count > 1)
			{
				hasDiceOnHand = true;
				index = 1;
				index2 = 1;
				AddDiceOnHandToVerticalList();
			}
			base.inputManager.AddCompanionAndEnemyDiceToVerticalList(chooseDiceActionRemoveNonValidDice: true);
			RemoveActionThatStartedChooseDiceStateFromNavigationList(hasDiceOnHand);
			enemiesAndCompanionOriginalHorizontalZoomableList = base.inputManager.verticalZoomableInstanceList[index].Duplicate();
			AddNewListForDiceOnDiceTargetCastSpace(index2);
		}
		else if (chooseDiceStateEnum == ChooseDiceStateEnum.OnlyEnemyDice)
		{
			base.inputManager.AddCompanionAndEnemyDiceToVerticalList(chooseDiceActionRemoveNonValidDice: true, addOnlyEnemies: true);
			enemiesAndCompanionOriginalHorizontalZoomableList = base.inputManager.verticalZoomableInstanceList.First().Duplicate();
			AddNewListForDiceOnDiceTargetCastSpace(0);
			base.inputManager.SetVerticalIndex(1);
		}
		else if (chooseDiceStateEnum == ChooseDiceStateEnum.PlayerHandDice)
		{
			base.inputManager.AddPlayerDiceInstanceToVerticalList(chooseDiceActionRemoveNonValidDice: true);
			playerOriginalHorizontalZoomableList = base.inputManager.verticalZoomableInstanceList.First().Duplicate();
			RemoveActionThatStartedChooseDiceStateFromNavigationList(hasDiceOnHand: true);
			AddNewListForDiceOnDiceTargetCastSpace(1);
		}
		base.inputManager.GoToFirstZoomableInstance();
		OnMovedToDiceInstanceChooseDiceState.Raise();
		freezeInput = false;
	}

	private void AddDiceOnHandToVerticalList()
	{
		base.inputManager.AddPlayerDiceInstanceToVerticalList(chooseDiceActionRemoveNonValidDice: true);
		playerOriginalHorizontalZoomableList = base.inputManager.verticalZoomableInstanceList.First().Duplicate();
		if (base.inputManager.verticalZoomableInstanceList[0].Count > 0)
		{
			base.inputManager.SetVerticalIndex(0);
		}
		else
		{
			base.inputManager.SetVerticalIndex(2);
		}
	}

	private void RemoveActionThatStartedChooseDiceStateFromNavigationList(bool hasDiceOnHand)
	{
		if (hasDiceOnHand && actionInstanceReference.Value.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			base.inputManager.verticalZoomableInstanceList.First().Remove(actionInstanceReference.Value);
		}
		else if (actionInstanceReference.Value.DiceOwnerEnum == DiceOwnerEnum.COMPANION)
		{
			base.inputManager.verticalZoomableInstanceList.Last().Remove(actionInstanceReference.Value);
		}
	}

	private void AddNewListForDiceOnDiceTargetCastSpace(int index)
	{
		List<ZoomableInstance> item = new List<ZoomableInstance>();
		base.inputManager.verticalZoomableInstanceList.Insert(index, item);
	}

	public override void Execute(float d)
	{
		if (!ReferenceSingleton<InputManager>.Instance.IsBattleInputEnabled)
		{
			return;
		}
		if (base.inputManager.DicePreviewOn)
		{
			if (base.inputManager.GetConfirmCanceInspectOrPlayButtonUp())
			{
				base.inputManager.TurnOffDicePreview(tutorialDicePreview: false);
			}
		}
		else
		{
			if (freezeInput)
			{
				return;
			}
			if (base.inputManager.GetInspectButtonUp())
			{
				DetailButtonPressed();
				return;
			}
			if (base.inputManager.GetPlayButtonUp())
			{
				OnCastActionButtonPressedJoystick.Raise();
				return;
			}
			if (base.inputManager.GetCancelButtonUp())
			{
				(base.inputManager.CurrentZoomableInstance as ActionInstance).OnMouseExit();
				OnCancelActionButtonPressedJoystick.Raise();
				return;
			}
			if (base.inputManager.ZoomableInstanceInput())
			{
				OnMovedToDiceInstanceChooseDiceState.Raise();
			}
			if (base.inputManager.GetSelectButtonUp())
			{
				freezeInput = true;
				DiceInstance diceInstance = base.inputManager.CurrentZoomableInstance as DiceInstance;
				if (diceInstance.DiceTargetCastSpaceInstance == null)
				{
					DiceInstanceNotOnDiceTargetCastSpace(diceInstance);
				}
				else
				{
					DiceInstanceOnDiceTargetCastSpace(diceInstance);
				}
			}
		}
	}

	private void DetailButtonPressed()
	{
		if (base.inputManager.CurrentZoomableInstance is DiceInstance)
		{
			base.inputManager.TurnOnDicePreview();
		}
	}

	private void DiceInstanceNotOnDiceTargetCastSpace(DiceInstance diceInstance)
	{
		DiceTargetCastSpaceInstance mostLeftDiceTargetCastSpaceInstanceEmpty = GetMostLeftDiceTargetCastSpaceInstanceEmpty();
		if (!IsAnyDiceTargetCastSpaceInstanceEmpty(diceInstance, mostLeftDiceTargetCastSpaceInstanceEmpty))
		{
			freezeInput = false;
			return;
		}
		if (!TryToSetupDiceInstanceDiceTargetCastSpaceInstanceAndUpdateDiceOnHandPosition(diceInstance, mostLeftDiceTargetCastSpaceInstanceEmpty))
		{
			freezeInput = false;
			return;
		}
		RemoveChosenDiceFromOldHorizontalZoomableInstanceList(diceInstance);
		InsertChosenDiceOnDiceTargetCastSpaceHorizontalZoomableInstanceList(diceInstance, mostLeftDiceTargetCastSpaceInstanceEmpty);
		MoveChosenDiceToDiceTargetCastSpaceInstancePosition(diceInstance, mostLeftDiceTargetCastSpaceInstanceEmpty);
		ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(null);
	}

	private DiceTargetCastSpaceInstance GetMostLeftDiceTargetCastSpaceInstanceEmpty()
	{
		for (int i = 0; i < diceTargetCastSpaceInstances.Count; i++)
		{
			if (!diceTargetCastSpaceInstances[i].AlreadyHaveADiceInstance)
			{
				return diceTargetCastSpaceInstances[i];
			}
		}
		return null;
	}

	private bool IsAnyDiceTargetCastSpaceInstanceEmpty(DiceInstance diceInstance, DiceTargetCastSpaceInstance diceTargetCastSpaceInstance)
	{
		if (diceTargetCastSpaceInstance == null)
		{
			diceInstance.PlayCantUseActionFeedback();
			return false;
		}
		return true;
	}

	private bool TryToSetupDiceInstanceDiceTargetCastSpaceInstanceAndUpdateDiceOnHandPosition(DiceInstance diceInstance, DiceTargetCastSpaceInstance diceTargetCastSpaceInstance)
	{
		if (!diceInstance.JoystickActionSelected())
		{
			return false;
		}
		diceInstance.OnMouseExit();
		diceInstance.SetDiceState(DiceState.OnDiceTargetCastSpace);
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		return true;
	}

	private void RemoveChosenDiceFromOldHorizontalZoomableInstanceList(DiceInstance diceInstance)
	{
		for (int i = 0; i < base.inputManager.verticalZoomableInstanceList.Count; i++)
		{
			if (base.inputManager.verticalZoomableInstanceList[i].Contains(diceInstance))
			{
				base.inputManager.verticalZoomableInstanceList[i].Remove(diceInstance);
				break;
			}
		}
	}

	private void InsertChosenDiceOnDiceTargetCastSpaceHorizontalZoomableInstanceList(DiceInstance diceInstance, DiceTargetCastSpaceInstance diceTargetCastSpaceInstance)
	{
		base.inputManager.verticalZoomableInstanceList[GetDiceTargetCastSpaceVerticalZoomableInstanceIndex(diceTargetCastSpaceInstance)].Insert(GetDiceTargetCastSpaceInstanceIndex(diceTargetCastSpaceInstance), diceInstance);
	}

	private void MoveChosenDiceToDiceTargetCastSpaceInstancePosition(DiceInstance diceInstance, DiceTargetCastSpaceInstance diceTargetCastSpaceInstance)
	{
		TweenCallback tweenCallback = null;
		if (base.inputManager.horizontalZoomableInstanceList.Count == 0)
		{
			tweenCallback = delegate
			{
				diceTargetCastSpaceInstance.ActionDrop(diceInstance, setDiceInstancePosition: false);
				base.inputManager.SetHorizontalIndex(GetDiceTargetCastSpaceInstanceIndex(diceTargetCastSpaceInstance));
				base.inputManager.SetVerticalIndex(GetDiceTargetCastSpaceVerticalZoomableInstanceIndex(diceTargetCastSpaceInstance));
				base.inputManager.GoToFirstZoomableInstance();
				freezeInput = false;
			};
		}
		else
		{
			base.inputManager.SetHorizontalIndex(0);
			base.inputManager.GoToFirstZoomableInstance();
			tweenCallback = delegate
			{
				diceTargetCastSpaceInstance.ActionDrop(diceInstance, setDiceInstancePosition: false);
				freezeInput = false;
			};
		}
		Vector3 diceOnTargetCastSpacePositionAdjustment = ReferenceSingleton<InputManager>.Instance.GetDiceOnTargetCastSpacePositionAdjustment(diceTargetCastSpaceInstance.transform.position, diceInstance: true);
		base.inputManager.MoveActionInstance(diceOnTargetCastSpacePositionAdjustment, tweenCallback);
	}

	private int GetDiceTargetCastSpaceInstanceIndex(DiceTargetCastSpaceInstance diceTargetCastSpaceInstance)
	{
		return diceTargetCastSpaceInstances.IndexOf(diceTargetCastSpaceInstance);
	}

	private int GetDiceTargetCastSpaceVerticalZoomableInstanceIndex(DiceTargetCastSpaceInstance diceTargetCastSpaceInstance)
	{
		int result = 1;
		if (chooseDiceStateEnum == ChooseDiceStateEnum.OnlyEnemyDice)
		{
			result = 0;
		}
		else if (chooseDiceStateEnum == ChooseDiceStateEnum.AllDice)
		{
			result = base.inputManager.verticalZoomableInstanceList.Count - 2;
		}
		return result;
	}

	private void DiceInstanceOnDiceTargetCastSpace(DiceInstance diceInstance)
	{
		diceInstance.OnMouseExit();
		diceInstance.DiceRemovedFromDiceTargetCastSpaceInstance();
		base.inputManager.KillActionInstanceMovementTween();
		if (diceInstance.DiceOwnerEnum == DiceOwnerEnum.PLAYER)
		{
			PlayerDiceOnDiceTargetCastSpaceChosen(diceInstance);
		}
		else
		{
			CompanionOrEnemyDiceOnDiceTargetCastSpaceChosen(diceInstance);
		}
	}

	private void PlayerDiceOnDiceTargetCastSpaceChosen(DiceInstance diceInstance)
	{
		diceInstance.SetDiceState(DiceState.ReturningToHandAfterTargetSpace);
		base.inputManager.verticalZoomableInstanceList[1].Remove(diceInstance);
		int originalHorizontalIndex = GetPlayerDiceInstanceIndexWithoutDiceOnTargetCastSpace(diceInstance);
		base.inputManager.verticalZoomableInstanceList.First().Insert(originalHorizontalIndex, diceInstance);
		diceInstance.GoBackToOriginalPositionAnimation(returningToHandAfterDrag: true, delegate
		{
			if (base.inputManager.HorizontalIndex == originalHorizontalIndex && base.inputManager.VerticalIndex == 0)
			{
				diceInstance.OnMouseOver();
			}
			freezeInput = false;
		});
		ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
		base.inputManager.SetVerticalIndex(0);
		base.inputManager.SetHorizontalIndex(originalHorizontalIndex);
	}

	private int GetPlayerDiceInstanceIndexWithoutDiceOnTargetCastSpace(DiceInstance diceInstance)
	{
		List<ZoomableInstance> list = playerOriginalHorizontalZoomableList.Duplicate();
		List<ZoomableInstance> diceTargetCastSpaceVerticalList = ReferenceSingleton<InputManager>.Instance.verticalZoomableInstanceList[1];
		list.RemoveAll((ZoomableInstance d) => diceTargetCastSpaceVerticalList.Contains(d));
		for (int i = 0; i < list.Count; i++)
		{
			if (diceInstance == list[i])
			{
				return i;
			}
		}
		return -1;
	}

	private void CompanionOrEnemyDiceOnDiceTargetCastSpaceChosen(DiceInstance diceInstance)
	{
		for (int i = 0; i < base.inputManager.verticalZoomableInstanceList.Count; i++)
		{
			if (base.inputManager.verticalZoomableInstanceList[i].Contains(diceInstance))
			{
				base.inputManager.verticalZoomableInstanceList[i].Remove(diceInstance);
				break;
			}
		}
		int enemyVerticalZoomableInstanceIndex = -1;
		if (chooseDiceStateEnum == ChooseDiceStateEnum.OnlyEnemyDice)
		{
			enemyVerticalZoomableInstanceIndex = 1;
		}
		else if (chooseDiceStateEnum == ChooseDiceStateEnum.AllDice)
		{
			enemyVerticalZoomableInstanceIndex = base.inputManager.verticalZoomableInstanceList.Count - 1;
		}
		int diceTargetCastSpaceVerticalIndex = enemyVerticalZoomableInstanceIndex - 1;
		int originalHorizontalIndex = GetEnemiesAndCompanionOriginalListHorizontalIndex(diceInstance, diceTargetCastSpaceVerticalIndex);
		base.inputManager.verticalZoomableInstanceList[enemyVerticalZoomableInstanceIndex].Insert(originalHorizontalIndex, diceInstance);
		diceInstance.GoBackToOriginalPositionAnimation(returningToHandAfterDrag: false, delegate
		{
			if (base.inputManager.HorizontalIndex == originalHorizontalIndex && base.inputManager.VerticalIndex == enemyVerticalZoomableInstanceIndex)
			{
				base.inputManager.GoToFirstZoomableInstance();
			}
			freezeInput = false;
		});
		base.inputManager.SetVerticalIndex(enemyVerticalZoomableInstanceIndex);
		base.inputManager.SetHorizontalIndex(originalHorizontalIndex);
	}

	private int GetEnemiesAndCompanionOriginalListHorizontalIndex(DiceInstance diceInstance, int diceTargetCastSpaceVerticalIndex)
	{
		List<ZoomableInstance> list = enemiesAndCompanionOriginalHorizontalZoomableList.Duplicate();
		List<ZoomableInstance> diceTargetCastSpaceVerticalList = ReferenceSingleton<InputManager>.Instance.verticalZoomableInstanceList[diceTargetCastSpaceVerticalIndex];
		list.RemoveAll((ZoomableInstance d) => diceTargetCastSpaceVerticalList.Contains(d));
		for (int i = 0; i < list.Count; i++)
		{
			if (diceInstance == list[i])
			{
				return i;
			}
		}
		return -1;
	}
}
